export type Frame = {
  kind: string;
  units: readonly number[];
};

export type FrameValidation =
  | { ok: true }
  | { ok: false; reason: "wrong-kind" | "malformed-unit" | "too-large" };

export function makeFrameValidator(
  expectedKind: string,
  maximumUnits: number
): (frame: Frame) => FrameValidation {
  const normalizedKind = expectedKind.trim();
  if (normalizedKind.length === 0) {
    throw new RangeError("expectedKind must not be empty");
  }
  if (!Number.isSafeInteger(maximumUnits) || maximumUnits <= 0) {
    throw new RangeError("maximumUnits must be a positive safe integer");
  }

  return (frame: Frame): FrameValidation => {
    if (frame.kind !== normalizedKind) {
      return { ok: false, reason: "wrong-kind" };
    }
    if (frame.units.some((unit) => !Number.isInteger(unit) || unit < 0 || unit > 255)) {
      return { ok: false, reason: "malformed-unit" };
    }
    if (frame.units.length >= maximumUnits) {
      return { ok: false, reason: "too-large" };
    }
    return { ok: true };
  };
}

