import { makeFrameValidator } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectRangeError(fn: () => unknown, message: string): void {
  let error: unknown;
  try {
    fn();
  } catch (caught) {
    error = caught;
  }
  assert(error instanceof RangeError, message);
}

for (const kind of ['', ' ', '\t\n']) {
  expectRangeError(() => makeFrameValidator(kind, 1), 'blank expected kinds must be rejected');
}
for (const maximum of [0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
  expectRangeError(() => makeFrameValidator('data', maximum), 'maximumUnits must be a positive safe integer');
}

const validate = makeFrameValidator('  data  ', 2);
deepEqual(validate({ kind: 'data', units: [] }), { ok: true }, 'empty units must be valid');
deepEqual(validate({ kind: 'data', units: [0, 255] }), { ok: true }, 'unit boundaries and inclusive maximum must be valid');
deepEqual(validate({ kind: ' data ', units: [] }), { ok: false, reason: 'wrong-kind' }, 'frame kind comparison must be exact');
deepEqual(validate({ kind: 'DATA', units: [] }), { ok: false, reason: 'wrong-kind' }, 'kind comparison must be case-sensitive');
deepEqual(validate({ kind: 'other', units: [-1, 2, 3] }), { ok: false, reason: 'wrong-kind' }, 'wrong-kind must take precedence');

for (const unit of [-1, 256, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  deepEqual(validate({ kind: 'data', units: [unit, 1, 2] }), { ok: false, reason: 'malformed-unit' }, 'malformed units must precede size validation');
}
deepEqual(validate({ kind: 'data', units: [1, 2, 3] }), { ok: false, reason: 'too-large' }, 'oversized valid frames must be rejected');

const units = [0, 255];
const frame = { kind: 'data', units };
const before = units.slice();
deepEqual(validate(frame), { ok: true }, 'normal frame must validate');
deepEqual(units, before, 'validation must not mutate the units array');
assert(frame.units === units, 'validation must not replace the frame units array');
units.push(256);
deepEqual(validate(frame), { ok: false, reason: 'malformed-unit' }, 'each validation must examine current input without hidden retained state');

